<script setup lang="ts">
import DateField from './DateField.vue';
import {title as displayTitle,sourceName,indicator,utc,time as beijingTime,duration,http} from '../presentation/zh';
import {ref,watch} from 'vue';import {post,safeOfficialUrl} from '../api/client';const props=defineProps<{token:string;seriesId:string}>();const from=ref(''),to=ref(''),asOf=ref(''),page=ref(0),data=ref<Record<string,any>>({}),error=ref(''),busy=ref(false);
async function load(){if(!props.seriesId)return;try{data.value=await post('/macro/history/query',props.token,{seriesId:props.seriesId,startPeriod:from.value||null,endPeriod:to.value||null,asOf:asOf.value?new Date(asOf.value+'+08:00').toISOString():null,page:page.value});}catch(e){error.value=(e as Error).message;}}
async function collect(){busy.value=true;error.value='';try{await post('/macro/history/collect',props.token,{seriesId:props.seriesId,startPeriod:from.value,endPeriod:to.value});await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
watch(()=>props.seriesId,()=>{page.value=0;void load();},{immediate:true});
</script>
<template><section class="history"><h3>官方历史请求与版本比较</h3><p>{{data.as_of_semantics||'历史发布时间与本地取得时间分别记录'}}</p><div class="filters"><label>观测起日 <DateField v-model="from"/></label><label>观测止日 <DateField v-model="to"/></label><label>本地可知截止时间 <DateField v-model="asOf" :include-time="true"/></label><button @click="page=0;load()">查询已有版本</button><button :disabled="busy||!from||!to" @click="collect">{{busy?'正在请求官方历史…':'请求选定日期官方历史'}}</button></div><p v-if="error" role="alert">{{error}}</p><p v-if="!data.revision_count">暂无可验证修订记录</p><p>同一观测日期的不同版本并列显示。响应生成时间不作为原始发布时间，缺失观测不自动判定为撤回。</p><article v-for="r in data.versions||[]" :key="r.id"><strong>{{r.observation_date}} · 本地版本 {{r.version}} · {{r.value??'缺失值'}}</strong><p>{{r.action==='Delete'?'官方明确删除动作，保留墓碑记录':'官方返回观测'}} · 原始发布时间 <time :title="'UTC原值：'+utc(r.source_published_at)">{{beijingTime(r.source_published_at,'官方发布时间未知')}}</time> · 官方历史版本时点 <time :title="'UTC原值：'+utc(r.source_vintage_at)">{{beijingTime(r.source_vintage_at,'尚未证实')}}</time> · 本地取得 {{beijingTime(r.collected_at)}}</p><p>响应生成时间 <time :title="'UTC原值：'+utc(r.response_prepared)">{{beijingTime(r.response_prepared)}}</time> · 来源更新时间头 <time :title="'UTC原值：'+utc(r.source_last_modified)">{{beijingTime(r.source_last_modified)}}</time></p><code>实际响应 SHA-256 {{r.response_hash}}</code><p><a v-if="safeOfficialUrl(r.url)" :href="r.url" target="_blank" rel="noopener noreferrer">查看官方历史请求</a></p></article><p v-if="!(data.versions||[]).length">暂无已保存历史查询版本</p><button :disabled="page===0" @click="page--;load()">上一页</button><button :disabled="(data.versions||[]).length<100" @click="page++;load()">下一页</button><details><summary>实际历史接口请求状态</summary><p v-for="r in data.requests||[]" :key="r.id">{{beijingTime(r.started_at)}} · {{http(r.http_status)}} · 观测 {{r.observations}} · {{r.error||'未记录错误'}} · 历史发布时间未证实</p></details></section></template>
<style scoped>.history{border-top:1px solid #324258;padding-top:16px;margin-top:20px}.filters{flex-wrap:wrap}label,input{max-width:100%}code,p{overflow-wrap:anywhere}</style>
